{
  "unit": {
    "id": "u-contract-baseline",
    "title": {
      "zh": "共享契约与前端基础设施冻结",
      "en": "Shared contracts and front-end infrastructure freeze"
    },
    "modules": [
      "bili.assembly.testkit",
      "bili.client.shared.design",
      "bili.client.shared.http",
      "bili.client.shared.i18n",
      "bili.client.shared.player",
      "bili.client.shared.uploader",
      "bili.contract.common",
      "bili.contract.event",
      "bili.contract.ledger",
      "bili.contract.state"
    ],
    "requirement_ids": [
      "R00-contract-freeze",
      "R18-frontend",
      "R20-data-ownership"
    ],
    "needs": [],
    "external_dependencies": [
      {
        "module": "bili.infra.db",
        "mode": "contract",
        "fixture_paths": [
          "contracts/samples/bili.infra.db.json"
        ]
      },
      {
        "module": "bili.playback.stream",
        "mode": "contract",
        "fixture_paths": [
          "contracts/samples/bili.playback.stream.json"
        ]
      }
    ],
    "verification": {
      "commands": [
        {
          "id": "design-check",
          "argv": [
            "node",
            "tools/verify-contracts.mjs",
            "--unit",
            "u-contract-baseline"
          ],
          "cwd": "."
        },
        {
          "id": "business-contracts-compile-and-fixtures",
          "argv": [
            "node",
            "--test",
            "contracts/tests/common.test.mjs"
          ],
          "cwd": "."
        },
        {
          "id": "business-fixtures-validate-and-negatives-rejected",
          "argv": [
            "node",
            "--test",
            "contracts/tests/event.test.mjs"
          ],
          "cwd": "."
        },
        {
          "id": "business-contract-has-no-reverse-dependency",
          "argv": [
            "node",
            "--test",
            "contracts/tests/state.test.mjs"
          ],
          "cwd": "."
        }
      ],
      "cases": [
        {
          "id": "design-contract-fixtures",
          "description": "设计与 fixture 验收（当前可执行，已实际执行）：u-contract-baseline 的叶子范围、写入文件独占、外部契约 fixture、needs 前置与 schema 样例",
          "requirement_ids": [
            "R00-contract-freeze",
            "R18-frontend",
            "R20-data-ownership"
          ],
          "command_ids": [
            "design-check"
          ]
        },
        {
          "id": "contracts-compile-and-fixtures",
          "description": "业务验收（未执行，待实现）：成功（已实际执行）：契约测试入口用基线 vendored Ajv 校验全部样例、断言伪造服务端字段与非法取值被拒绝、并检查写请求均已声明幂等键与请求上下文；strict tsc --noEmit 另由 tools/contracts-tsc.mjs 在集成阶段执行；目标模块 bili.contract.common；测试入口 contracts/tests/common.test.mjs",
          "requirement_ids": [
            "R00-contract-freeze",
            "R18-frontend",
            "R20-data-ownership"
          ],
          "command_ids": [
            "business-contracts-compile-and-fixtures"
          ]
        },
        {
          "id": "fixtures-validate-and-negatives-rejected",
          "description": "业务验收（未执行，待实现）：成功：全部样例通过 Schema 校验，且 5 个负例（本地时区时间/带空格 ID/浮点金额/缺 hasMore/缺必填）全部被拒绝（已实际执行）；目标模块 bili.contract.event；测试入口 contracts/tests/event.test.mjs",
          "requirement_ids": [
            "R00-contract-freeze",
            "R18-frontend",
            "R20-data-ownership"
          ],
          "command_ids": [
            "business-fixtures-validate-and-negatives-rejected"
          ]
        },
        {
          "id": "contract-has-no-reverse-dependency",
          "description": "业务验收（未执行，待实现）：失败面：任何共享契约模块依赖业务模块时必须报错阻断（policy contract-not-business-dependent 为 error）；目标模块 bili.contract.state；测试入口 contracts/tests/state.test.mjs",
          "requirement_ids": [
            "R00-contract-freeze",
            "R18-frontend",
            "R20-data-ownership"
          ],
          "command_ids": [
            "business-contract-has-no-reverse-dependency"
          ]
        }
      ],
      "resources": [
        {
          "id": "unit-db",
          "kind": "database",
          "description": "本单元独占的 RDS schema/实例（迁移后执行；单测禁止共享同一 schema）",
          "isolation": "unit"
        },
        {
          "id": "unit-port",
          "kind": "port",
          "description": "本单元 HTTP/WS 测试端口独占分配（含网关与 Worker 健康端口）",
          "isolation": "unit"
        },
        {
          "id": "unit-tmp",
          "kind": "filesystem",
          "description": "本单元独立临时目录与 fixture 目录，禁止写其他单元目录",
          "isolation": "unit"
        },
        {
          "id": "unit-oss-prefix",
          "kind": "service",
