      "types": [
        {
          "name": "Id",
          "description": {
            "zh": "统一实体标识：字符串，禁止用自增整数做外部契约",
            "en": "Unified entity id: string, auto-increment integers are forbidden in contracts"
          },
          "schema": {
            "type": "string",
