          },
          "schema": {
            "type": "integer",
            "minimum": 0,
            "description": "最小货币单位整数 / Integer minor units"
          }
        },
        {
          "name": "PageRequest",
          "description": {
            "zh": "唯一分页请求形态：游标优先，pageSize 上限 100",
            "en": "Single pagination request: cursor first, pageSize max 100"
          },
          "schema": {
            "type": "object",
            "additionalProperties": false,
            "description": "禁止第二种分页形态 / No second pagination shape",
