            "en": "Common contract type entry\n"
          }
        }
      ],
      "types": [
        {
          "name": "Id",
          "description": {
            "zh": "统一实体标识：字符串，禁止用自增整数做外部契约",
            "en": "Unified entity id: string, auto-increment integers are forbidden in contracts"
          },
          "schema": {
            "type": "string",
            "pattern": "^[A-Za-z0-9_-]{1,64}$",
            "description": "全站统一字符串 ID / Unified string id"
          }
        },
        {
          "name": "ModuleId",
          "description": {
            "zh": "架构模块标识：小写点分（用于事件的生产/消费模块字段）",
            "en": "Architecture module id: lowercase dotted, used by event producer and consumer fields"
          },
          "schema": {
            "type": "string",
            "pattern": "^[a-z0-9][a-z0-9-]*(.[a-z0-9][a-z0-9-]*)*$",
            "description": "模块 id，如 bili.catalog.event / Module id"
          }
        },
        {
          "name": "Timestamp",
          "description": {
            "zh": "统一时间：UTC ISO 8601，必须带 Z 后缀（禁止本地偏移）",
            "en": "Unified time: UTC ISO 8601 with a mandatory Z suffix; local offsets are rejected"
          },
          "schema": {
            "type": "string",
