              "message": {
                "type": "string",
                "description": "可展示信息 / Displayable message"
              },
              "requestId": {
                "type": "string",
                "description": "请求 ID / Request id"
              },
              "details": {
                "type": "object",
                "additionalProperties": true,
                "description": "结构化细节 / Structured details"
              }
            },
            "required": [
              "code",
              "message",
              "requestId"
            ]
          }
        },
        {
          "name": "IdempotencyKey",
          "description": {
            "zh": "写操作幂等键：同一业务动作重放必须返回同一结果",
            "en": "Write idempotency key: replaying one business action must return the same result"
          },
          "schema": {
            "type": "string",
            "pattern": "^[A-Za-z0-9:_-]{8,128}$",
            "description": "客户端生成，服务端去重存储 / Client generated, server deduplicated"
          }
        },
        {
          "name": "RequestContext",
          "description": {
            "zh": "请求上下文：所有写入口必填（网关或调用方注入）",
            "en": "Request context, required by every write entry point and injected by the gateway or caller"
          },
          "schema": {
            "type": "object",
            "additionalProperties": false,
            "description": "网关注入；userId 由鉴权结果填充，不接受调用方伪造 / Injected by the gateway; userId comes from the authenticated principal",
            "properties": {
              "requestId": {
                "type": "string",
                "description": "请求 ID / Request id"
              },
              "userId": {
                "$ref": "urn:normify:bili.contract.common:Id"
              },
              "deviceId": {
                "type": "string",
                "description": "设备标识 / Device id"
              },
              "appVersion": {
                "type": "string",
                "description": "客户端版本 / Client app version"
              },
              "platformCode": {
                "type": "string",
                "enum": [
                  "web",
                  "ios",
                  "android",
                  "harmony",
                  "tv",
                  "openapi"
