                "description": "平台代码 / Platform code"
              },
              "idempotencyKey": {
                "$ref": "urn:normify:bili.contract.common:IdempotencyKey"
              },
              "traceId": {
                "type": "string",
                "description": "链路追踪 ID / Trace id"
              }
            },
            "required": [
              "requestId",
              "platformCode"
            ]
          }
        },
