            "required": [
              "amount",
              "currency"
            ]
          }
        },
        {
          "name": "MoneyAmount",
          "description": {
            "zh": "金额数值（最小货币单位整数）",
            "en": "Money amount in minor units"
          },
          "schema": {
            "type": "integer",
            "minimum": 0,
            "description": "最小货币单位整数 / Integer minor units"
          }
        },
        {
          "name": "PageRequest",
          "description": {
            "zh": "唯一分页请求形态：游标优先，pageSize 上限 100",
            "en": "Single pagination request: cursor first, pageSize max 100"
          },
          "schema": {
            "type": "object",
            "additionalProperties": false,
            "description": "禁止第二种分页形态 / No second pagination shape",
            "properties": {
              "cursor": {
                "type": "string",
                "description": "分页游标 / Page cursor"
              },
              "pageSize": {
                "type": "integer",
                "minimum": 1,
                "maximum": 100,
                "description": "每页条数 / Page size"
              },
              "sort": {
                "type": "string",
                "enum": [
                  "latest",
                  "hot",
                  "score",
                  "custom"
